insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_41_v1'
from (values
('127.244.d.14',3,'Which sentence uses correct capitalization and punctuation?','["Our manager, Ms. Lee, approved the budget on Monday.", "Our manager ms. Lee. approved the budget, on Monday", "our Manager, ms. Lee, approved the Budget on Monday", "Our manager Ms. lee approved the budget on monday."]'::jsonb,0,'Proper nouns and sentence starts are capitalized; commas set off appositives.','original'),
('127.244.d.14',4,'A handwritten note to a client should be legible mainly because:','["it shortens the message", "the client must be able to read and trust the message", "it lowers postage", "it removes the need for a signature"]'::jsonb,1,'Illegible writing blocks communication.','original'),
('127.244.d.15',3,'Which spelling is correct in a business email?','["recieve", "riceive", "receive", "receeve"]'::jsonb,2,'The rule ''i before e except after c'' applies.','original'),
('127.244.d.15',4,'Which sentence contains a spelling error?','["Our schedule is separate from theirs.", "Please acknowledge the shipment by Friday.", "The accountant reviewed the receipt.", "Please acknowledge the shipment by Friday and sign the recipt."]'::jsonb,3,'''Recipt'' should be ''receipt''.','original'),
('127.244.d.17',3,'Before giving an oral presentation to a client, a speaker should:','["rehearse and organize main points", "avoid eye contact", "start without a plan", "memorize every word with no notes"]'::jsonb,0,'Preparation improves delivery.','original'),
('127.244.d.17',4,'During a sales presentation, which speaking technique best keeps the audience engaged?','["turning away from the audience", "varying tone and making eye contact", "reading slides word for word", "speaking in a monotone"]'::jsonb,1,'Engagement requires eye contact and vocal variety.','original'),
('127.244.d.18',3,'Three coworkers are preparing a proposal. The team works best when each member:','["competes with the others", "waits to be told every step", "has a clear role and shares updates", "works alone and hides progress"]'::jsonb,2,'Clear roles and updates support teamwork.','original'),
('127.244.d.18',4,'A team member keeps missing deadlines. The most productive first response is to:','["redo the work silently", "publicly criticize the member", "ignore it", "talk privately to find the cause and agree on a plan"]'::jsonb,3,'Direct, private discussion solves problems.','original'),
('127.244.d.1.A',3,'A professional who writes clear emails and speaks respectfully to customers is demonstrating:','["effective oral and written communication", "careless habits", "poor planning", "avoidance"]'::jsonb,0,'Both skills build business relationships.','original'),
('127.244.d.1.A',4,'A supervisor asks you to explain a delayed order to an upset client. The best approach is to:','["blame another department", "state the facts calmly and offer a solution", "avoid the client", "send a vague message"]'::jsonb,1,'Clarity and solutions build trust.','original'),
('127.244.d.1.B',3,'Sharing ideas, listening to others, and dividing tasks among classmates on a project shows:','["competition", "avoidance", "collaboration skills", "working alone"]'::jsonb,2,'Collaboration shares work and ideas.','original'),
('127.244.d.1.B',4,'A team disagrees about a report layout. The collaborative response is to:','["vote without talking", "quit the project", "let the loudest voice win", "discuss options and agree on one that fits the purpose"]'::jsonb,3,'Consensus serves the goal.','original'),
('127.244.d.1.C',3,'Arriving on time, dressing appropriately, and using courteous language in the workplace show:','["professionalism", "indifference", "carelessness", "rebellion"]'::jsonb,0,'Professional conduct fits the setting.','original'),
('127.244.d.1.C',4,'A coworker posts a frustrated message about a client on a public page. A professional would:','["ignore company policy", "keep client concerns private and address them through proper channels", "join in the posting", "repost it"]'::jsonb,1,'Confidentiality is professional.','original'),
('127.244.d.1.D',3,'Completing assigned tasks fully and on time without constant reminders shows:','["procrastination", "shortcuts", "a productive work ethic", "avoidance"]'::jsonb,2,'Reliability reflects ethic.','original'),
('127.244.d.1.D',4,'An employee finishes her work early. A strong work ethic suggests she should:','["wait idly", "leave quietly", "distract others", "ask what else needs to be done"]'::jsonb,3,'Initiative shows ethic.','original'),
('127.244.d.1.E',3,'An employee notices an error that benefits the company on a customer''s invoice. Integrity means:','["correcting the error", "hiding it", "keeping the extra money", "blaming the customer"]'::jsonb,0,'Honesty requires fixing mistakes.','original'),
('127.244.d.1.E',4,'Complying with company policies and laws regarding customer data is part of:','["optional behavior", "choosing the ethical course of action", "avoiding rules", "cutting corners"]'::jsonb,1,'Compliance is ethical conduct.','original'),
('127.244.d.1.F',3,'Ranking tasks by urgency and following a calendar shows:','["disorganization", "delay", "time-management skills", "poor focus"]'::jsonb,2,'Prioritizing manages time.','original'),
('127.244.d.1.F',4,'Three tasks are due today: a client call, a report due tomorrow, and a weekly filing. The best first step is to:','["file first", "wait until evening", "skip the call", "make the client call first, then schedule the rest by deadline"]'::jsonb,3,'Urgent, time-sensitive items go first.','original'),
('127.244.d.2.A',3,'A good email about a product launch should first state the purpose, then give details in:','["logical order", "no order", "random order", "reverse alphabetical order"]'::jsonb,0,'Logical sequencing aids understanding.','original'),
('127.244.d.2.A',4,'Which list of steps for training a new hire is in logical sequence?','["Explain, assess, welcome, demonstrate", "Welcome, explain duties, demonstrate tasks, assess performance", "Demonstrate, assess, welcome, explain", "Assess performance, welcome, demonstrate, explain"]'::jsonb,1,'Steps build in order.','original'),
('127.244.d.2.B',3,'To find a company''s return policy, a worker should:','["guess", "skip it", "locate and read the policy in the handbook or website", "ask a stranger"]'::jsonb,2,'Reading official information is reliable.','original'),
('127.244.d.2.B',4,'A written memo says ''effective Monday.'' To interpret it, you should check the memo''s:','["font", "paper color", "logo", "date to know which Monday"]'::jsonb,3,'Context determines meaning.','original'),
('127.244.d.2.C',3,'The statement ''Our product has the highest sales in the region'' is a fact only if it:','["can be verified with sales data", "sounds convincing", "is said by the boss", "is repeated often"]'::jsonb,0,'Facts are verifiable.','original'),
('127.244.d.2.C',4,'Words like ''I believe'' and ''in my view'' usually signal:','["a law", "an opinion", "a fact", "a statistic"]'::jsonb,1,'Key words flag opinion.','original'),
('127.244.d.2.D',3,'A bar chart shows that sales rose each quarter. This visual helps a reader:','["hide data", "avoid reading", "see trends quickly", "change numbers"]'::jsonb,2,'Charts show patterns.','original'),
('127.244.d.2.D',4,'A map in a delivery report is most useful for showing:','["interest rates", "profits", "employee ages", "locations and distances"]'::jsonb,3,'Maps convey geography.','original'),
('127.244.d.2.E',3,'Instead of ''a lot of stuff,'' a precise report would state:','["''250 units of inventory''", "''a pile''", "''many things''", "''some items''"]'::jsonb,0,'Precision aids clarity.','original'),
('127.244.d.2.E',4,'Which sentence is the most concise and clear?','["Friday is a day, so form.", "Please submit the form by Friday.", "It would be very much appreciated if you could possibly submit the form at some point near Friday.", "Submit form maybe."]'::jsonb,1,'Concise wording communicates clearly.','original'),
('127.244.d.2.F',3,'A well-written paragraph begins with a topic sentence and then provides:','["blank space", "unrelated jokes", "supporting details", "a new topic"]'::jsonb,2,'Coherent paragraphs develop one idea.','original'),
('127.244.d.2.F',4,'Transition words such as ''first,'' ''next,'' and ''finally'' help writing by:','["adding length", "hiding errors", "removing meaning", "showing the logical progression of ideas"]'::jsonb,3,'Transitions guide readers.','original'),
('127.244.d.3.A',3,'A student gathers statistics from a company website and a printed journal for a report. She is using:','["printed and electronic resources", "only memory", "no sources", "only opinions"]'::jsonb,0,'Multiple sources support research.','original'),
('127.244.d.3.A',4,'Which source is most reliable for current industry statistics?','["a social media rumor", "a government or industry association report", "a friend''s guess", "an anonymous blog"]'::jsonb,1,'Credible sources are trustworthy.','original'),
('127.244.d.3.B',3,'Restating an author''s idea in your own words while giving credit is:','["deleting", "copying", "paraphrasing", "plagiarizing"]'::jsonb,2,'Paraphrasing still requires a citation.','original'),
('127.244.d.3.B',4,'Which is an acceptable paraphrase practice?','["Leaving out the source", "Changing one word", "Copying a paragraph", "Rewriting the idea in your own words and citing the source"]'::jsonb,3,'Original wording plus citation is honest.','original'),
('127.244.d.3.C',3,'Listing the author, title, publisher, and date of a source is called:','["documenting the source", "hiding", "editing", "formatting only"]'::jsonb,0,'Documentation gives credit.','original'),
('127.244.d.3.C',4,'Failing to document a source in a report can lead to:','["higher accuracy", "plagiarism", "extra credit", "a longer report"]'::jsonb,1,'Uncredited use is plagiarism.','original'),
('127.244.d.3.D',3,'A group wants to know which snack customers prefer. A useful first step in a survey is to:','["use leading questions", "ask only friends", "write clear, unbiased questions", "skip planning"]'::jsonb,2,'Good questions yield good data.','original'),
('127.244.d.3.D',4,'A survey of 100 customers shows 60 prefer option A. What percent prefer A?','["6%", "160%", "40%", "60%"]'::jsonb,3,'60 / 100 = 60%.','original'),
('127.244.d.3.E',3,'Before interviewing a business owner for a class project, you should:','["prepare questions and schedule a time", "ask rude questions", "show up unannounced", "skip research"]'::jsonb,0,'Preparation shows respect.','original'),
('127.244.d.3.E',4,'After an interview, a good follow-up action is to:','["ignore the person", "send a thank-you note", "lose your notes", "post their answers publicly without permission"]'::jsonb,1,'Gratitude builds relationships.','original'),
('127.244.d.3.F',3,'A student creates a report that includes a chart from a spreadsheet and a table from a web page. This is a project that incorporates:','["unsupported claims", "only handwriting", "data imported from several sources", "hidden files"]'::jsonb,2,'Combining sources builds documents.','original'),
('127.244.d.3.F',4,'When importing a chart into a report, you should:','["use it without review", "alter the numbers", "hide the source", "cite the data source and check accuracy"]'::jsonb,3,'Credit and verify.','original'),
('127.244.d.4.A',3,'For a quick question to a coworker down the hall, the most appropriate telecommunications method is:','["an instant message or phone call", "a formal letter", "a printed memo", "certified mail"]'::jsonb,0,'Fast needs call for fast channels.','original'),
('127.244.d.4.A',4,'A manager needs signed approval from a client overseas by tomorrow. Which method is most appropriate?','["a postcard", "email with an electronic signature", "standard mail", "word of mouth"]'::jsonb,1,'Speed and record are needed.','original'),
('127.244.d.4.B',3,'When answering a business call, proper etiquette is to:','["stay silent", "answer with ''what?''", "identify yourself and the company politely", "hang up"]'::jsonb,2,'A polite greeting is professional.','original'),
('127.244.d.4.B',4,'Using speakerphone in an open office during a confidential call:','["is required", "is harmless", "is courteous", "violates good etiquette and ethics"]'::jsonb,3,'Confidentiality matters.','original'),
('127.244.d.5.A',3,'Learning terms such as ''invoice,'' ''revenue,'' and ''client'' builds:','["professional vocabulary", "delays", "slang", "errors"]'::jsonb,0,'Vocabulary supports clarity.','original'),
('127.244.d.5.A',4,'In a business meeting, a more professional word for ''buy'' might be:','["grab", "purchase", "snatch", "score"]'::jsonb,1,'Formal vocabulary suits business.','original'),
('127.244.d.5.B',3,'An effective oral presentation includes an introduction, body, and:','["argument", "apology", "conclusion", "delay"]'::jsonb,2,'Presentations need structure.','original'),
('127.244.d.5.B',4,'A speaker''s pace is too fast for the audience. She should:','["read faster", "whisper", "speed up", "slow down and pause between key points"]'::jsonb,3,'Pacing aids understanding.','original'),
('127.244.d.5.C',3,'A salesperson explaining a product''s benefits to a customer is delivering a:','["sales presentation", "tax form", "resume", "memo"]'::jsonb,0,'Sales talks persuade buyers.','original'),
('127.244.d.5.C',4,'A manager reviewing quarterly results with the board is giving a:','["sales pitch to consumers", "report presentation", "training video", "press release"]'::jsonb,1,'Reports inform decision makers.','original'),
('127.244.d.5.D',3,'When leaving a voicemail for a client, you should state your name, number, and:','["a long story", "nothing else", "the reason for the call", "a joke"]'::jsonb,2,'Clear messages save time.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_41_v1'
